package com.projexa.coaching.students.controller;
import com.projexa.coaching.students.entity.Student; import com.projexa.coaching.students.service.StudentService; import com.projexa.coaching.common.responses.ApiResponse; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/v1/students") public class StudentController { private final StudentService service; public StudentController(StudentService service){this.service=service;} @GetMapping @PreAuthorize("hasAuthority('dashboard.read') or hasAuthority('settings.manage') or hasAuthority('students.read')") public ApiResponse<List<Student>> list(){return ApiResponse.ok(service.list());} @GetMapping("/{id}") @PreAuthorize("hasAuthority('students.read') or hasAnyRole('INSTITUTE_OWNER','INSTITUTE_ADMIN')") public ApiResponse<Student> get(@PathVariable UUID id){return ApiResponse.ok(service.get(id));} @PostMapping @PreAuthorize("hasAuthority('settings.manage') or hasAuthority('students.create')") public ApiResponse<Student> create(@RequestBody Student item){return ApiResponse.ok(service.create(item));} @PutMapping("/{id}") @PreAuthorize("hasAuthority('settings.manage') or hasAuthority('students.update')") public ApiResponse<Student> update(@PathVariable UUID id,@RequestBody Student item){return ApiResponse.ok(service.update(id,item));} @DeleteMapping("/{id}") @PreAuthorize("hasAuthority('settings.manage') or hasAuthority('students.delete')") public ApiResponse<Void> delete(@PathVariable UUID id){service.delete(id);return ApiResponse.ok(null);} }